export const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));

export function quoteLink(product = '', category = 'Flanges', specification = {}) {
    const parameters = new URLSearchParams({ category, product });
    for (const field of ['material', 'standard', 'facing']) if (specification[field]) parameters.set(field, specification[field]);
    return `contact.html?${parameters}`;
}

