export function documentPage(path, title, description, content, parent = ['flanges.html', 'Flanges']) {
    const crumbs = path === 'index.html' ? '' : `<nav class="vf-breadcrumb vf-wrap" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span>${parent && parent[0] !== path ? `<a href="${parent[0]}">${parent[1]}</a><span aria-hidden="true">/</span>` : ''}<span aria-current="page">${escapeHtml(title)}</span></nav>`;
    const structured = { '@context': 'https://schema.org', '@type': 'WebPage', name: title, description, url: `https://www.valtronforge.com/${path}` };
    const galleryAssets = path === 'gallery.html' ? '<link rel="stylesheet" href="css/gallery.css"><script src="js/gallery.js" defer></script>' : '';
    return `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)} | Valtron Forge &amp; Fittings</title><meta name="description" content="${escapeHtml(description)}"><link rel="canonical" href="https://www.valtronforge.com/${path}"><link rel="icon" href="img/valtron-logo.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.10.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/catalogue.css">${galleryAssets}<script type="application/ld+json">${JSON.stringify(structured).replace(/</g, '\\u003c')}</script><script src="js/catalogue.js" defer></script>${path === 'index.html' ? '<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=Oswald:wght@500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/home.css"><script src="js/home.js" defer></script>' : ''}</head>
<body class="vf-site${path === 'index.html' ? ' vf-home' : ''}"><a class="vf-skip" href="#main">Skip to content</a>${navigation(path)}${crumbs}<main id="main">${content}</main>${footer()}</body></html>\n`;
}

