    return `${heading('Project enquiries', 'Request a Quote', 'Flanges, buttweld fittings and forged fittings. Share your specification with our Mumbai team.')}<section class="vf-wrap vf-contact-layout"><form id="vf-quote-form"><fieldset><legend>01 / Product requirement</legend><div class="vf-form-grid"><label>Product category *<select name="category" id="quote-category" required><option>Flanges</option><option>Buttweld Fittings</option><option>Forged Fittings</option></select></label>${field('product', 'Product / connection type', 'text', true, 'maxlength="160"')}${field('material', 'Material / grade')}${field('size', 'Nominal size')}${field('rating', 'Pressure class / PN / fitting class')}${field('standard', 'Standard / edition')}<label data-flange-field>Flange facing<input name="facing" id="quote-facing" list="flange-facings"></label><datalist id="flange-facings"><option value="Raised Face (RF)"><option value="Flat Face (FF)"><option value="Ring Type Joint (RTJ)"><option value="Tongue and Groove"><option value="Male and Female"><option value="Lap Joint"></datalist><label data-fitting-field hidden>Schedule / wall / end connection<input name="connection" id="quote-connection" disabled></label>${field('quantity', 'Quantity (pieces)', 'number', true, 'min="1" step="1"')}${field('drawing', 'Drawing number / revision')}</div></fieldset><fieldset><legend>02 / Contact details</legend><div class="vf-form-grid">${field('name', 'Your name', 'text', true, 'autocomplete="name"')}${field('company', 'Company', 'text', false, 'autocomplete="organization"')}${field('email', 'Email', 'email', true, 'autocomplete="email"')}${field('phone', 'Telephone', 'tel', true, 'autocomplete="tel"')}</div><label>Additional requirements<textarea name="message" rows="4" maxlength="2000"></textarea></label></fieldset><p class="vf-form-note">Fields marked * are required. Enquiry details are passed to WhatsApp; no files are uploaded through this form.</p><button class="vf-button" type="submit"><i class="fab fa-whatsapp" aria-hidden="true"></i> Continue to WhatsApp</button><p id="quote-status" role="status"></p><noscript><p>The enquiry form requires JavaScript. Email your specification to <a href="mailto:sales@valtronforge.com">sales@valtronforge.com</a> or call <a href="tel:+919619770076">+91 96197 70076</a>.</p></noscript></form><aside class="vf-contact-aside"><p class="vf-eyebrow">Sales enquiries</p><h2>Talk to Valtron</h2><a href="tel:+919619770076">+91 96197 70076</a><a href="mailto:sales@valtronforge.com">sales@valtronforge.com</a><h3>Mumbai, India</h3><address>12/13 Badrika Ashram Building,<br>1st Khetwadi, Near Alankar Cinema,<br>Girgaon, Mumbai,<br>Maharashtra 400004, India</address><p>Drawing attachments can be sent by email or through the WhatsApp conversation.</p><a class="vf-text-link" href="https://www.google.com/maps/search/?api=1&amp;query=12%2F13%20Badrika%20Ashram%20Building%20Khetwadi%20Mumbai" target="_blank" rel="noopener noreferrer">Open map <i class="fas fa-external-link-alt" aria-hidden="true"></i></a></aside></section>
<section class="vf-section vf-office-section" id="head-office" aria-labelledby="head-office-title"><div class="vf-wrap"><div class="vf-section-heading"><div><p class="vf-eyebrow">Our head office</p><h2 id="head-office-title">Mumbai, India</h2></div><a class="vf-text-link" href="https://www.google.com/maps/search/?api=1&amp;query=12%2F13%20Badrika%20Ashram%20Building%20Khetwadi%20Mumbai" target="_blank" rel="noopener noreferrer">Get directions <i class="fas fa-external-link-alt" aria-hidden="true"></i></a></div><figure class="vf-office-map"><div class="vf-office-map-image"><img src="img/contact-world-map.png" alt="World map with the Mumbai head office marked on India's west coast" width="1440" height="720" loading="lazy"><a class="vf-office-pin" href="https://www.google.com/maps/search/?api=1&amp;query=12%2F13%20Badrika%20Ashram%20Building%20Khetwadi%20Mumbai" target="_blank" rel="noopener noreferrer" aria-label="Valtron head office, Mumbai, India: open map in a new tab" title="Valtron head office - Mumbai, India"><i class="fas fa-map-marker-alt" aria-hidden="true"></i><span aria-hidden="true">Mumbai</span></a></div><figcaption><strong>Valtron Forge &amp; Fittings</strong><address>12/13 Badrika Ashram Building, 1st Khetwadi, Near Alankar Cinema,<br>Girgaon, Mumbai, Maharashtra 400004, India</address></figcaption></figure></div></section>`;
