export function referenceDetailPage(reference) {
    const group = referenceGroups[reference.kind];
    const targets = [...references, ...products.map(product => ({ slug: product.slug, title: product.name })), ...Object.values(referenceGroups).map(category => ({ slug: category.path.replace('.html', ''), title: category.title }))];
    const related = reference.related.filter(slug => !hiddenMaterialSlugs.has(slug)).map(slug => {
        const target = targets.find(candidate => candidate.slug === slug);
        if (!target) throw new Error(`Unknown related reference ${slug} in ${reference.slug}`);
        return target;
    });
    return `${productNavigation(reference.slug)}${heading(group.label, escapeHtml(reference.title), escapeHtml(reference.intro))}
<section class="vf-wrap vf-reference-detail"><aside><figure class="vf-detail-figure"><a href="${reference.image}" target="_blank" rel="noopener noreferrer" aria-label="View full-size ${escapeHtml(reference.name)} reference image" title="View full-size reference image"><img src="${reference.image}" alt="${escapeHtml(reference.alt)}" width="640" height="480"><span class="vf-image-zoom" aria-hidden="true"><i class="fas fa-search-plus"></i></span></a><figcaption>${escapeHtml(reference.caption)}</figcaption></figure><div class="vf-actions">${button(quoteLink(reference.title, 'Flanges', reference.enquiry), 'Request a Quote')}</div><a class="vf-text-link" href="${group.path}">${escapeHtml(group.title)} ${arrow}</a></aside><div>${reference.sections.map(([title, text]) => `<section><h2>${escapeHtml(title)}</h2><p>${escapeHtml(text)}</p></section>`).join('')}<p class="vf-reference-note">Selection reference only. Offered scope, technical compliance and availability are confirmed against the complete project enquiry.</p></div></section>${productInformation(reference)}
<section class="vf-section vf-soft-band"><div class="vf-wrap vf-spec-layout"><div><p class="vf-eyebrow">Enquiry checklist</p><h2>Details for ${escapeHtml(reference.name)}</h2><p>Specify the complete joint and design conditions. This checklist is not a dimensional table or an engineering approval.</p></div><div class="vf-table-scroll"><table class="vf-spec-table"><caption>${escapeHtml(reference.name)} specification details</caption><thead><tr><th scope="col">Item</th><th scope="col">Requirement</th></tr></thead><tbody>${reference.checks.map(([name, text]) => `<tr><th scope="row">${escapeHtml(name)}</th><td>${escapeHtml(text)}</td></tr>`).join('')}</tbody></table></div></div></section>
<section class="vf-section vf-wrap"><p class="vf-eyebrow">Continue the specification</p><h2>Related references</h2><ul class="vf-link-list">${related.map(candidate => `<li><a href="${candidate.slug}.html">${escapeHtml(candidate.title)} ${arrow}</a></li>`).join('')}<li><a href="flanges.html">Flange connection types ${arrow}</a></li></ul></section>`;
}